-- Revocable public project reports. The opaque id is generated by the API
-- only when a member publishes a project; private projects never resolve
-- through the public read function below.
ALTER TABLE "projects"
  ADD COLUMN IF NOT EXISTS "is_public" BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS "public_id" TEXT,
  ADD COLUMN IF NOT EXISTS "published_at" TIMESTAMPTZ(6);

CREATE UNIQUE INDEX IF NOT EXISTS "projects_public_id_key" ON "projects"("public_id");

-- RLS remains unchanged: anonymous callers do not gain SELECT access to the
-- underlying projects/jobs/designs tables. This SECURITY DEFINER function is
-- the sole public choke point and emits an explicit allowlist of fields.
CREATE OR REPLACE FUNCTION public.get_public_project_share(p_public_id TEXT)
RETURNS JSONB
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  WITH shared_project AS (
    SELECT
      p.id,
      p.name,
      p.description,
      p.updated_at,
      o.slug AS org_name
    FROM projects p
    JOIN organizations o ON o.id = p.org_id
    WHERE p.public_id = p_public_id
      AND p.is_public = true
    LIMIT 1
  ),
  latest_target AS (
    SELECT t.name, t.pdb_id
    FROM targets t
    JOIN shared_project p ON p.id = t.project_id
    ORDER BY t.created_at DESC
    LIMIT 1
  ),
  candidate_rows AS (
    SELECT
      d.id,
      d.seed,
      d.rank,
      d.provenance,
      j.tool,
      d.created_at,
      CASE
        WHEN jsonb_typeof(d.metrics -> 'length') = 'number'
          AND (d.metrics ->> 'length') ~ '^[0-9]{1,6}$'
          THEN (d.metrics ->> 'length')::INT
        WHEN jsonb_typeof(d.metrics -> 'sequence') = 'string'
          THEN length(d.metrics ->> 'sequence')
        ELSE NULL
      END AS sequence_length,
      jsonb_strip_nulls(jsonb_build_object(
        'computational__actifptm', COALESCE(d.metrics -> 'computational__actifptm', d.metrics -> 'actifptm', d.metrics -> 'actif_ptm'),
        'computational__interface_residues', COALESCE(d.metrics -> 'computational__interface_residues', d.metrics -> 'interface_residues', d.metrics -> 'interfaceResidues', d.metrics -> 'n_interface_residues'),
        'computational__boltz2_min_ipsae', COALESCE(d.metrics -> 'computational__boltz2_min_ipsae', d.metrics -> 'min_ipsae', d.metrics -> 'ipsae', d.metrics -> 'ipSAE', d.metrics -> 'best_ipsae'),
        'computational__boltz2_iptm', COALESCE(d.metrics -> 'computational__boltz2_iptm', d.metrics -> 'iptm', d.metrics -> 'ipTM'),
        'computational__boltz2_lis', COALESCE(d.metrics -> 'computational__boltz2_lis', d.metrics -> 'lis', d.metrics -> 'LIS'),
        'computational__boltz2_complex_iplddt', COALESCE(d.metrics -> 'computational__boltz2_complex_iplddt', d.metrics -> 'complex_iplddt', d.metrics -> 'complexIpLddt', d.metrics -> 'iplddt'),
        'shape_complementarity', COALESCE(d.metrics -> 'shape_complementarity', d.metrics -> 'interfaceSC', d.metrics -> 'interface_sc'),
        'pdockq', COALESCE(d.metrics -> 'pdockq', d.metrics -> 'pDockQ', d.metrics -> 'dockq'),
        'aromatic_fraction', d.metrics -> 'aromatic_fraction',
        'hydrophobic_fraction', d.metrics -> 'hydrophobic_fraction',
        'bio__aggregation_propensity', COALESCE(d.metrics -> 'bio__aggregation_propensity', d.metrics -> 'aggregation_propensity'),
        'bio__immunogenicity_proxy', COALESCE(d.metrics -> 'bio__immunogenicity_proxy', d.metrics -> 'immunogenicity_proxy'),
        'bio__disulfide_potential', COALESCE(d.metrics -> 'bio__disulfide_potential', d.metrics -> 'disulfide_potential'),
        'bio__topology_helix_frac', COALESCE(d.metrics -> 'bio__topology_helix_frac', d.metrics -> 'topology_helix_frac'),
        'bio__topology_loop_frac', COALESCE(d.metrics -> 'bio__topology_loop_frac', d.metrics -> 'topology_loop_frac')
      )) AS scoring_metrics
    FROM designs d
    JOIN jobs j ON j.id = d.job_id
    JOIN shared_project p ON p.id = j.project_id
    WHERE j.status IN ('succeeded', 'partial')
    ORDER BY d.rank ASC NULLS LAST, d.created_at DESC
    LIMIT 100
  )
  SELECT jsonb_build_object(
    'project', jsonb_build_object(
      'name', p.name,
      'description', p.description,
      'updatedAt', p.updated_at
    ),
    'org', jsonb_build_object('name', p.org_name),
    'target', (
      SELECT jsonb_build_object('name', t.name, 'pdbId', t.pdb_id)
      FROM latest_target t
    ),
    'summary', jsonb_build_object(
      'completedJobs', (
        SELECT count(*)
        FROM jobs j
        WHERE j.project_id = p.id
          AND j.status IN ('succeeded', 'partial')
      ),
      'designsGenerated', (
        SELECT count(*)
        FROM designs d
        JOIN jobs j ON j.id = d.job_id
        WHERE j.project_id = p.id
          AND j.status IN ('succeeded', 'partial')
      )
    ),
    'candidates', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', c.id,
          'seed', c.seed,
          'rank', c.rank,
          'tool', c.tool,
          'provenance', c.provenance,
          'length', c.sequence_length,
          'metrics', c.scoring_metrics
        )
        ORDER BY c.rank ASC NULLS LAST, c.created_at DESC
      )
      FROM candidate_rows c
    ), '[]'::jsonb)
  )
  FROM shared_project p;
$$;

-- The function is intentionally callable without a database session identity;
-- its is_public predicate and field allowlist are the access boundary.
GRANT EXECUTE ON FUNCTION public.get_public_project_share(TEXT) TO PUBLIC;
